package com.jiugeng.erp.product;
import static com.jiugeng.erp.product.ProductTypes.*;import com.jiugeng.erp.iam.AuthenticatedActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.List;import org.springframework.context.annotation.Profile;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @Profile("!mock") @RequestMapping("/api/v1/products") class ProductController{private final ProductService service;ProductController(ProductService service){this.service=service;}
@GetMapping @PreAuthorize("hasAuthority('products.read')") List<ProductView> products(Authentication a){return service.products(has(a,"suppliers.read"));}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('products.read')") ProductView product(@PathVariable String id,Authentication a){return service.product(id,has(a,"suppliers.read"));}
@PostMapping @PreAuthorize("hasAuthority('products.write')") ProductView create(@Valid@RequestBody ProductRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.create(r.input(),actor,has(a,"suppliers.read"));}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('products.write')") ProductView update(@PathVariable String id,@Valid@RequestBody ProductRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.update(id,r.input(),actor,has(a,"suppliers.read"));}
@PostMapping("/{id}/disable") @PreAuthorize("hasAuthority('products.write')") ProductView disable(@PathVariable String id,@Valid@RequestBody VersionRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.disable(id,r.version(),actor,has(a,"suppliers.read"));}
private boolean has(Authentication a,String authority){return a.getAuthorities().stream().anyMatch(v->v.getAuthority().equals(authority));}
record ProductRequest(@NotBlank@Size(max=64)String productCode,@Size(max=200)String productName,@Size(max=200)String nameZh,@Size(max=100)String productType,@Size(max=1000)String description,ProductStatus status,Long version,@NotEmpty@Size(max=100)List<@Valid VariantRequest>variants){ProductInput input(){String name=productName==null||productName.isBlank()?nameZh:productName;return new ProductInput(productCode,name,productType,description,status,version,variants.stream().map(VariantRequest::input).toList());}}
record VariantRequest(String id,@NotBlank@Size(max=64)String skuCode,@NotBlank@Size(max=200)String variantName,@Size(max=200)String itemDimensions,@Size(max=200)String packageDimensions,@DecimalMin(value="0",inclusive=false)@Digits(integer=9,fraction=3)BigDecimal packageWeightGrams,VariantStatus status,@Size(max=36)String imageAssetId,@Size(max=500)String imageUrl,Long version,@Size(max=50)List<@Valid SupplierRequest>suppliers,@Size(max=100)List<@Valid MaterialRequest>materials){VariantInput input(){return new VariantInput(id,skuCode,variantName,itemDimensions,packageDimensions,packageWeightGrams,status,imageAssetId,imageUrl,version,suppliers==null?List.of():suppliers.stream().map(SupplierRequest::input).toList(),materials==null?List.of():materials.stream().map(MaterialRequest::input).toList());}}
record SupplierRequest(@NotBlank@Size(max=36)String supplierId,@Size(max=500)String purchaseUrl,@Size(max=500)String remark,boolean primary){SupplierAssignment input(){return new SupplierAssignment(supplierId,purchaseUrl,remark,primary);}}
record MaterialRequest(@NotBlank@Size(max=36)String materialId,@NotNull@DecimalMin(value="0",inclusive=false)BigDecimal standardQuantity,@NotBlank@Size(max=32)String unit,@DecimalMin("0")@DecimalMax("1")BigDecimal lossRate,@Size(max=1000)String remark,Boolean enabled){MaterialAssignment input(){return new MaterialAssignment(materialId,standardQuantity,unit,lossRate,remark,enabled==null||enabled);}}
record VersionRequest(@Min(0)long version){}
}
